// A small, predictable formatting vocabulary; no HTML is executed or imported.
export function descriptionRuns(text){const runs=[],re=/\*\*([^*]+)\*\*|\*([^*]+)\*/g;let index=0,m;while((m=re.exec(text))){if(m.index>index)runs.push({text:text.slice(index,m.index)});runs.push({text:m[1]||m[2],bold:!!m[1],italic:!!m[2]});index=re.lastIndex;}if(index<text.length)runs.push({text:text.slice(index)});return runs;}
export function descriptionHtml(text,escape){return String(text||'').split('\n').map(line=>{const bullet=/^\s*[-•]\s+/.test(line);const content=bullet?line.replace(/^\s*[-•]\s+/,''):line;return `<div class="description-line${bullet?' description-bullet':''}">${bullet?'<span aria-hidden="true">• </span>':''}${descriptionRuns(content).map(run=>run.bold?'<strong>'+escape(run.text)+'</strong>':run.italic?'<em>'+escape(run.text)+'</em>':escape(run.text)).join('')||'<br>'}</div>`;}).join('');}
